# Q8 (round 2): replace the Q8a-f results of /output/report.json by the revised set (uv forward model, double ratios, ladder, null, error budget, physical mapping)
import json
p='/output/report.json'; r=json.load(open(p))
r['results']=[x for x in r['results'] if not x['quantity'].startswith('Q8')]
r['recipe']=[x for x in r['recipe'] if not x['description'].startswith('Q8')]
r['caveats']=[x for x in r['caveats'] if not x.startswith('Q8')]
i=r['interpretation'].find('\n\nQ8:'); 
if i>=0: r['interpretation']=r['interpretation'][:i]
A=lambda n,v:{"name":n,"value":v}
common=[A("data","pbcor cubes Xb55 (2-1), Xb47 (4-3), Xb4f/Xb4d/Xb4b (3-2); moment-0 |v-2780|<350 km/s; exact beam-difference smoothing kernels; positions N (0,+2.55\"), S (-0.15,-2.55\"), Bridge (+0.3,+0.15\") from the Q1 deblend"),A("flux scale","10% per OUS; cancels in N/S contrasts built from the same two maps"),A("Xb4f","used as the matched-uv reference for the Xb47 4-3 (same compact-configuration class: beam ratio Xb47/Xb4f = 0.72 (major), 0.76 (minor) vs wavelength ratio 0.75; Xb55/Xb4f 1.51/1.69 vs 1.51)")]
def R(q,v,u,unit,conf,ev,tgt,extra=()):
    r['results'].append({"quantity":q,"value":v,"uncertainty":u,"unit":unit,"confidence":conf,"evidence":ev,"target":tgt,"assumptions":common+list(extra)})
R("Q8a: uncorrected N/S ratio of T43/T32 (Tb, matched beam) and its instrumental error budget; reference array for the 3-2",
  "HCN, Xb47 4-3 / Xb4f 3-2 at the Xb4f beam 6.2x3.7\": N 0.425, S 0.319, Bridge 0.364 -> N/S 1.33 (circular 6.5\": 1.19; Xb55 beam 9.5x6.4\": 1.26, reproducing team-b p0015 1.26+-0.09). HCO+: N 0.547, S 0.483 -> N/S 1.13 (1.09; 1.11). Monte Carlo over beam (3 beams), position vs local peak, 0.3\" jitter of the N and S sample positions, 0.3\" per-axis Xb47-vs-Xb4f astrometric shift and thermal noise (4000 draws): HCN N/S = 1.23, 68% [1.10,1.35], 95% [1.00,1.49] (sigma 0.13), P(N/S>1)=0.97; HCO+ 1.10, 68% [1.02,1.19], 95% [0.94,1.30], P(>1)=0.89. 16 Q1 deblend variants (N,S,Bridge,Outer fitted together; Xb4f 3-2 and Xb47 4-3): HCN N/S 1.47 (range 1.43-1.70; N 0.395, S 0.268), HCO+ 1.08 (0.83-1.23). With Xb4d or Xb4b 3-2 as the denominator the contrast is 0.97-1.13, but those arrays lose 12-40% of the 3-2 flux relative to Xb4f (S more than N, Q8d), which mechanically pulls N/S toward 1: they are biased low-recovery references, not independent evidence that the contrast is 1.",
  "statistical +-0.04 (HCN) / +-0.015 (HCO+) at the Xb4f beam; total instrumental budget (beam, position, astrometry, noise) sigma 0.13 (HCN), 0.09 (HCO+); the 10% scale per OUS cancels. NOT included: uv recovery (Q8d-e)","ratio","medium","out/q8b/mc_NS_summary.csv, out/q8b/deblend_variants_NS.csv, out/q8/T43_T32_contrast.csv; scripts/q8_matched.py, q8_contrast.py, q8b_diagnostics.py","N, S, Bridge")
R("Q8b: recovery-robust differential diagnostics: HCN/HCO+ double ratio, line/continuum double ratio, empirical null from control positions",
  "(i) HCN/HCO+ double ratio of the N/S contrast: 1.18+-0.04 (Xb4f beam, Xb4f 3-2), 1.09 (6.5\" circ.), 1.13 (Xb55 beam); MC over beam/position/astrometry 1.11, 68% [1.06,1.17], 95% [1.02,1.23], P(>1)=0.99: a ~10% HCN-specific excess that common-mode recovery, calibration and pointing cannot produce (they act on both lines). (ii) line/continuum double ratio (line N/S of T43/T32 divided by the continuum Xb47/Xb4f N/S ratio 1.20 at the same beam): HCN 1.11+-0.04, HCO+ 0.95+-0.01 (statistical). The continuum N/S 1.20 is the size of the whole HCO+ contrast and of 80% of the HCN one. (iii) control positions: T43/T32 (Xb47/Xb4f at the Xb4f beam) at 31-43 positions with 3-2 and 4-3 S/N>10-20 across the disk; pairs 5.1\" apart (35-65 pairs, not independent): the fraction of pairs with |ln(R1/R2)| >= the observed N/S is 0.26-0.34 (HCN; 0.18-0.43 for circ. 6.5\"), 0.6-0.7 (HCO+); the HCN/HCO+ double ratio 1.18 is exceeded by 23-28% of pairs. Median |ln| of random pairs is 0.16-0.19 (a 17-21% scatter in T43/T32 between positions 5\" apart).",
  "double ratio 1.11 [1.02,1.23] (95%, MC); null fractions from 35-110 non-independent pairs, +-0.1","ratio / fraction","medium","out/q8b/double_ratio_HCN_HCOp.csv, line_continuum_double_ratio.csv, control_positions_null.csv, control_positions_double_ratio_null.csv, mc_NS_summary.csv; scripts/q8b_diagnostics.py","N, S, disk",
  [A("null","position-to-position scatter includes real spatial variation of T43/T32, so it is a conservative (large) null"),A("continuum","continuum compared at matched beam, 258 vs 347 GHz, Xb4f vs Xb47")])
R("Q8c: excitation ladder 2-1 / 3-2 / 4-3 at the Xb55 beam (9.5x6.4\"), N, S, Bridge, both lines (no size model)",
  "HCN, Xb4f 3-2: T32/T21 N 0.403, S 0.366, Bridge 0.389 (N/S 1.10); T43/T32 N 0.363, S 0.289, Bridge 0.337 (N/S 1.26); T43/T21 (only Xb47 and Xb55, no 3-2 array) N 0.146, S 0.106, Bridge 0.131: N/S 1.38, N/Bridge 1.12. HCO+: T32/T21 N/S 1.05, T43/T32 1.11, T43/T21 N 0.242, S 0.208: N/S 1.16. Both steps are >=1 for N/S in both lines (monotonic in sense), so it is NOT only the Xb47 step that differs; but the 3-2 array changes how the contrast splits between the steps (Xb4d 3-2: T32/T21 N/S 1.33, T43/T32 1.04; Xb4b: 1.31, 1.05) while T43/T21 N/S is the same by construction. S/Bridge < 1 in HCN T32/T21 (0.94) and T43/T32 (0.86). Deblended (16 variants): T32/T21 N/S 1.04 (0.51-1.77, S 2-1 poorly deblended).",
  "statistical +-0.01-0.03 per ratio; recovery of Xb55 (2-1) vs Xb4f vs Xb47 not corrected (same configuration class, wavelength scaling 1.5 / 1 / 0.75)","ratio","low","out/q8b/ladder_Xb55beam.csv, out/q8c/T43_T21_NS.csv, out/q8b/deblend_variants_NS.csv; scripts/q8b_diagnostics.py, q8e_summary.py","N, S, Bridge")
R("Q8d: source-model uv forward model calibrated on the three Band-6 arrays (Xb4b, Xb4d, Xb4f; line and continuum): effective short-baseline limits and the predicted Xb47-vs-Xb4f recovery",
  "Model: each position = compact + extended circular Gaussian (4 free parameters per position and line; continuum 3), seen through a short-baseline high-pass (Gaussian taper, taper without dirty-beam normalisation, or sharp cut) with a 'largest scale kept' L = 0.53 lambda/Bmin; Xb47 and Xb55 share the Xb4f configuration (Bmin ratio lognormal(0,0.25)); 70 calibration data (native-beam 3-2 peaks of Xb4b/Xb4d/Xb4f + 1.7\", Xb4d/Xb4f and Xb4b/Xb4f 3-2 ratios at 3 matched beams, continuum Xb4d/Xb4f, Xb4b/Xb4f at 2 beams) and 40 parameters, emcee. All six fits reproduce the calibration data (chi2_min 51-66 for 70 data; posterior-predictive Xb4d/Xb4f HCN N 0.86 S 0.71 Bridge 0.80, Xb4b/Xb4f N 0.75 S 0.58 vs observed 0.875 0.720 0.809 / 0.792 0.601 0.651). The data fix the ARRAY ORDER robustly (Xb4f least lossy) but the ABSOLUTE loss of Xb4f/Xb47 depends on the prior on Bmin: (A) unbounded L (data-preferred): L_f >= 24\" (36 [24,50]), L_d 15.5 [13.4,17.1]\", L_b 13.4 [11.8,14.7]\" -> Xb4f and Xb47 ~lossless; this needs Bmin(Xb4f) ~3 m, below the 12 m dish diameter: physically impossible. (B) physical Bmin>=15 m (L<=8.2\" at 266 GHz): L_f at the cap (7.8-8.1\"), L_d 6.3 [6.0,6.5]\" (Bmin ~20 m), L_b 5.7 [5.4,5.9]\" (~22 m), L_47 5.2 [4.4,5.9]\" (cap 6.2\"); chi2 +14 (taper) or +2 (taper without normalisation) relative to A; the sharp-cut variant is rejected by the continuum spectral-index bound (see below). Predicted 3-2 peak recovery at the Xb4f beam: A: Xb4f 0.99 N, 0.94 S; Xb47(4-3)/Xb4f(3-2) = 0.98 N, 0.95 S, 0.97 Bridge. B: Xb4f 0.62-0.87 N, 0.17-0.23 S (an extended envelope invisible to all arrays); Xb47/Xb4f = 0.68-0.74 N, 0.52-0.54 S, 0.61-0.65 Bridge (equal compact/extended excitation). Constraint from the continuum: Xb47/Xb4f continuum 2.29 N, 1.91 S, 2.18 Bridge implies spectral index alpha(258-347 GHz) = 2.9 N, 2.3 S, 2.7 Bridge in A and 4.0-4.2 N, 3.8-4.0 S, 4.3-4.5 Bridge in B (sharp cut: 5-8, impossible for dust+free-free); draws with alpha outside [1.5,4.5] are removed (B keeps 52-63%, sharp-cut B 0%).",
  "model-dependent: Xb47/Xb4f peak recovery 0.52-0.74 (physical) to 0.95-0.98 (unbounded); differential N-vs-S loss 1.0 (unbounded) to 1.3-1.4 (physical); the 4-3 sizes are assumed equal to the 3-2 sizes (or compact x0.7)","ratio","low","out/q8c/array_params.csv, predictions.csv, fit_*.log; scripts/q8c_uvmodel.py, q8d_predict.py","N, S, Bridge",
  [A("uv model","Gaussian-taper high-pass H=1-exp(-(q/qmin)^2), L = 2 sqrt(ln2)/(pi qmin) = 0.53 lambda/Bmin; image peak at matched beam B for a Gaussian component of FWHM s: A s^2 [1/sqrt(S1 S2)-1/sqrt((S1+L^2)(S2+L^2))]/n_a, S_i=s^2+B_i^2, n_a = dirty-beam normalisation (point source fully recovered); variants without n_a and with a sharp cut"),A("priors","s log-flat 0.08-1.5\", s_ext 1.5-30\", amplitudes 0.01-100 K, L log-flat 0.3-60\" (A) or 0.3-8.2\" (B: Bmin>=15 m), flux scale of Xb4d, Xb4b relative to Xb4f lognormal(0,0.14), Bmin(Xb47)/Bmin(Xb4f) and Bmin(Xb55)/Bmin(Xb4f) lognormal(0,0.25)"),A("continuum","own geometry per position; alpha bound 1.5-4.5 for dust + free-free is an assumption")])
R("Q8e: N/S contrast of T43/T32 after the Xb47-vs-Xb4f uv correction, with the full error budget (the primary number of Q8)",
  "HCN: pooled (50% physical-Bmin family, 50% unbounded family; 4-3 compact size x1 or x0.7; r_c ~U(0.4,1) with r_e solved to reproduce the observed ratios; observed N/S from the Q8a Monte Carlo) N/S = 1.07, 68% [0.89,1.26], 95% [0.76,1.42], P(N/S>1) = 0.64; physical family 0.96 [0.84,1.10], P(>1)=0.39; unbounded family 1.18 [1.04,1.32], P(>1)=0.90. HCO+: pooled 1.00 [0.88,1.12], 95% [0.79,1.24], P(>1)=0.49 (physical 0.93 [0.84,1.01]; unbounded 1.07 [0.97,1.16]). Independent continuum-calibrated estimate (equal spectral index at N and S, continuum Xb47/Xb4f N/S 1.198 removed): HCN 1.03 [0.92,1.13] (sigma(alpha_N-alpha_S) = 0.5: 1.02 [0.86,1.22]), HCO+ 0.92 [0.85,0.99]. The team-b contrast (1.26+-0.09, 2.9 sigma; ours 1.33+-0.04 stat) therefore corresponds to 0.4 sigma-equivalent (P=0.64) after the Xb47 recovery correction and the position/beam/astrometry budget: it is not established. The residual HCN-over-HCO+ excess (double ratio 1.11 [1.02,1.23]) is not separable from random position-to-position scatter (Q8b).",
  "pooled HCN 1.07 +0.19 -0.18 (68%), HCO+ 1.00 +0.12 -0.12; the split between the two families (0.96 vs 1.18) is the model systematic that data cannot reduce without the true Xb4f/Xb47 minimum baselines (visibilities)","ratio","low","out/q8c/NS_corrected_pooled.csv, NS_continuum_equal_alpha.csv, NS_correction.csv; scripts/q8e_summary.py","N, S",
  [A("pooling","equal weight on the physically bounded (taper, taper-raw; alpha-bounded) and unbounded (taper, taper-raw, sharp) families, a judgement; sharp-cut physical fit excluded by the alpha bound"),A("observed input","N/S Monte Carlo of Q8a (beam, position, astrometry, noise) multiplied by the model correction factor (true/observed N/S, median 0.78 physical, 0.98 unbounded)")])
R("Q8f: Tkin vs density vs size: what the contrast means physically, with both interpretations",
  "Pure size/filling difference with equal excitation (compact+extended Gaussians with the fitted N and S sizes) gives HCN contrast 1.02-1.13 (P(>=1.33)<=0.1 for plausible r_e; Q8 round 1, scripts/q8_forward.py), so size alone does not make N look more excited; the remaining effects are recovery (Q8d-e) and real excitation. Extended-component T43/T32 (the component that carries 70-97% of the Xb4f/Xb47-beam peak: compact share of the unfiltered 3-2 peak at the Xb4f beam N 0.15-0.22, S 0.03-0.16, Bridge 0.08-0.17) solved from the observed ratios: physical family HCN r_ext N 0.57, S 0.54 (HCO+ 0.75, 0.78); unbounded family HCN N 0.43, S 0.31 (HCO+ 0.57, 0.51). RADEX one-zone inversion (logN(HCN)=15.5, equal n, T from the ratio): physical family T_N/T_S = 1.2 [0.96,1.43] (log n=6; HCN), 1.3 at log n=5.5; HCO+ 0.83 [0.63,1.04]; unbounded family T_N/T_S = 1.7 [1.4,1.9] (log n=6) to 1.9 [1.5,2.2] (log n=5), e.g. 38 vs 22 K at n=1e6; HCO+ 1.2-1.6. Overall T_N/T_S ~ 0.8-1.9, consistent with 1, with a face-value upper end of ~1.9 that needs a lossless Xb4f/Xb47, which the minimum-baseline argument disfavours; at equal T the corresponding density difference is Tkin-degenerate (0.2-0.4 dex in n). Compact (nuclear) component alone: it carries only 3-21% of the 4-3 peak at the Xb4f beam, and its T43/T32 is unconstrained by these data (if the extended gas has a common ratio 0.30, the compact N/S ratio needed is 1.8 in the unbounded family, 1.04-1.3 in the physical family with r_c>1.5 i.e. unphysical unless r_ext>=0.45): a nuclear excitation difference is allowed but not required.",
  "T_N/T_S 0.8-1.9 depending on the uv family; extended-gas ratios +-0.05; one-zone RADEX, T-n degeneracy remains","ratio","low","out/q8c/physical_mapping_extended.csv, out/q8c/compact_component_limits.csv, out/q8/size_only_forward.csv, out/q8/tkin_vs_density_inversion.csv; scripts/q8e_summary.py, q8_forward.py","N, S",
  [A("excitation","RADEX LVG grids out/q4c/grid4_*.npz, Tbg 2.73 K, logN(HCN) 15.5, shared beam filling"),A("r_c prior","compact-component T43/T32 ~U(0.4,1); extended solved")])
R("Q8g: per-line source sizes, beam filling of the dense (compact) gas and compact share, N / S / Bridge (joint uv-model fit)",
  "HCN compact FWHM: N 0.38\" [0.33,0.43] (physical) / 0.35\" [0.29,0.40] (unbounded), S 0.40\" [0.36,0.43] / 0.35\" [0.32,0.39], Bridge 0.50\" [0.44,0.56] / 0.47\" [0.42,0.53]; extended FWHM: N 3.5\" [3.1,3.9] / 2.6\" [2.2,3.0], S 18\" [15,23] / 9.5\" [9.0,10.2], Bridge 6.6\" [5.9,7.5] / 5.6\" [5.0,6.2] (HCO+ similar, see geometry_uvmodel.csv). Compact-gas beam filling (peak, HCN): Xb47 4.2x2.75\" N 0.012 (0.010-0.015), S 0.013, Bridge 0.021; Xb4f 5.9x3.6\" N 0.007, S 0.007, Bridge 0.011; Xb4d 0.95x0.75\" N 0.14-0.17, S 0.15-0.18; Xb55 0.002-0.003. Extended-gas filling at the Xb47 / Xb4f beam: N 0.50 / 0.35 (physical), 0.36 / 0.23 (unbounded); S 0.96 / 0.93, 0.88 / 0.80; Bridge 0.78 / 0.66, 0.72 / 0.58. Compact share of the unfiltered 3-2 peak: Xb47 beam N 0.18-0.25, S 0.05-0.24, Bridge 0.12-0.23; Xb4f beam N 0.15-0.22, S 0.03-0.16, Bridge 0.08-0.17 (round-1 growth-curve values 0.28/0.21 N, 0.23/0.16 S are within the family spread). Only the 3-2 sizes are measured (and continuum sizes are free); 2-1 and 4-3 sizes are assumed equal (4-3 compact x0.7 tested). The extended-filling parameter u of Q12c (N 1.6 [1.1,3.0], S 1.1) is a different quantity and is not re-derived here.",
  "sizes 10-20% (physical vs unbounded family); extended sizes S/N poorly constrained (S 9-23\")","arcsec / fraction","medium","out/q8c/geometry_uvmodel.csv, out/q8/filling_by_beam.csv; scripts/q8f_geometry.py, q8_forward.py","N, S, Bridge")
R("Q8h: what a matched ~1\" 1-0 (or 2-1 at Xb4d resolution) map would add (not in the archive)",
  "The archive has 2-1 only at 9x6\" (Xb55), 3-2 at 0.25/0.95/6\" and 4-3 only at 4.2x2.7\" (Xb47): no common-uv ladder exists. A 1-0 or 2-1 map at ~1\" from the same configuration as a 4-3 map would (i) give the T-n degeneracy a third step, (ii) allow recovery to be calibrated on a ladder with the same Bmin/lambda, and (iii) resolve the compact component (0.4\") from the extended gas at N. Without it the compact-component excitation is unconstrained and the N-S contrast is bounded to N/S <= 1.4 (95%, corrected) rather than measured.",
  "qualitative","","medium","scripts/q8e_summary.py","N, S")
r['recipe'].append({"order":len(r['recipe'])+1,"stage":"modelling","description":"Q8 (round 2): (1) q8b_diagnostics.py: HCN/HCO+ double ratios, 2-1/3-2/4-3 ladder at the Xb55 beam, line/continuum double ratio, control-position null (grid 1.4\", pairs 4.6-5.6\" apart, S/N>10,20), Monte Carlo of N/S (beam, pos/peak, 0.3\" jitter, 0.3\" astrometric shift, noise; 4000 draws) and the 16 Q1 deblend variants; (2) q8c_uvmodel.py: joint emcee fit (160 walkers, 40000-60000 steps, DE moves) of compact+extended Gaussians per position/line/continuum and short-baseline parameters of Xb4b/Xb4d/Xb4f (Xb47/Xb55 tied to Xb4f by wavelength and a lognormal Bmin ratio), variants taper/taper_raw/sharp x unbounded/physical (Bmin>=15 m); (3) q8d_predict.py: recoveries, posterior-predictive check, continuum spectral-index bound 1.5-4.5, correction to N/S with r_c~U(0.4,1) and r_e solved, 4-3 compact size x1/x0.7; (4) q8e_summary.py: pooled corrected contrast, continuum equal-alpha estimate, T43/T21, RADEX mapping; (5) q8f_geometry.py: sizes, filling, compact shares.","scripts":["scripts/q8b_diagnostics.py","scripts/q8c_uvmodel.py","scripts/q8d_predict.py","scripts/q8e_summary.py","scripts/q8f_geometry.py","scripts/build_report_q8b.py"]})
r['interpretation']+=("\n\nQ8: The N-vs-S excitation contrast of the dense gas (T43/T32 N/S 1.26-1.33 for HCN, 1.1 for HCO+; team-b p0015) is not established as a Tkin effect, and it is not a size effect either. (1) Size/filling alone with equal excitation gives <=1.1. (2) Xb4d/Xb4b 3-2 are lossy references (12-40% less 3-2 than Xb4f, S more than N) and cannot be used to say the contrast is 1; Xb4f is the uv-matched reference for Xb47 (same configuration class). (3) A uv forward model calibrated on all three Band-6 arrays (line and continuum) fits the array ratios well but cannot fix the absolute short-spacing loss of Xb4f/Xb47: if Xb4f/Xb47 were lossless the corrected HCN contrast is 1.18 [1.04,1.32]; with the physical minimum baseline (>=15 m) Xb47 loses 25-50% of the extended flux relative to Xb4f, S more than N, and the contrast is 0.96 [0.84,1.10]; the continuum Xb47/Xb4f N/S 1.20 (equal spectral index) points to the latter (HCN 1.03, HCO+ 0.92). Pooled: HCN 1.07 [0.89,1.26] (95% 0.76-1.42), HCO+ 1.00 [0.88,1.12]. (4) A ~10% HCN-specific excess over HCO+ (double ratio 1.11 [1.02,1.23]) survives the common-mode cancellation but is within the scatter of control position pairs (23-28% exceed it). (5) 70-97% of the 3-2/4-3 peak at these beams is extended gas (compact beam filling ~1%): the measured ratio refers to the extended gas, T_N/T_S ~0.8-1.9 (consistent with 1), and the nuclear dense gas at 0.4\" is not constrained by the 4-6\" ladder. Confidence low: the temperature difference between the nuclei is neither detected nor excluded at <=1.4 (95%). A ~1\" 1-0/2-1 map from the same configuration as the 4-3 would break the degeneracy; it is not in the archive.")
r['caveats'].append("Q8: (a) the Xb47/Xb4f short-baseline loss is inferred from a model, not measured: the two families (unbounded vs Bmin>=15 m) give corrected HCN N/S 1.18 vs 0.96 and the 50/50 pooling is a judgement; real uv holes are not Gaussian and cleaning partially restores flux; (b) Xb47 and Xb55 are assumed to share Xb4f's configuration/minimum baseline (supported by the beam ratios = wavelength ratios, not by visibilities); (c) 4-3 sizes assumed equal to 3-2 (compact x0.7 tested); (d) the continuum alpha bound (1.5-4.5) and equal-alpha estimate are assumptions; (e) position samples of blended maps (deblended contrast is larger, 1.47 uncorrected, but suffers the same recovery); (f) control-pair null uses 31-59 positions and non-independent pairs, and includes real T43/T32 variations; (g) one-zone RADEX with shared filling; compact-component excitation unconstrained; (h) emcee chains of 40-60k steps (tau 400-1700) are adequate for medians/68% intervals but not for tails.")
json.dump(r,open(p,'w'),indent=1)
